# vhdl_ls needs a vhdl_ls.toml listing the project's files and libraries.
# In the directory with your sources, type `:vhd` in nvim (or `vhd` in a
# `:term` shell). It only runs when you ask.
#
#   vhd           # .vhd/.vhdl files in the current dir
#   vhd -r        # include subdirectories
#   vhd --std 1993
#   vhd -f        # overwrite a hand-written vhdl_ls.toml
#
# Files go in `defaultlib` unless references like `use mylib.my_pkg.all;`
# show they belong to another library. Vendor libraries (e.g. `unisim`) must
# be added by hand. Remove the generated file's first line to keep manual edits.
#
# `:vhd` restarts the language server. After running `vhd` in a shell, restart
# nvim to apply the changes.
"""vhd: generate vhdl_ls.toml from the VHDL files in the current directory."""

import argparse
import glob
import json
import re
import sys
from pathlib import Path

OUTPUT = "vhdl_ls.toml"
MARKER = "# Generated by vhd"
DEFAULT_LIB = "defaultlib"  # vhdl_ls rejects a library named "work"
BUILTIN_LIBS = {"ieee", "std", "work"}

# Strings and character literals are matched too, so that "--" or a quote
# inside one is not mistaken for the start of a comment or string.
NOISE = re.compile(r"""--[^\n]*|/\*.*?\*/|"(?:[^"\n]|"")*"|'[^\n]'""", re.S)

# Units that other files can name as <library>.<unit>
PRIMARY = [
    re.compile(r"\bentity\s+(\w+)\s+is\b"),
    re.compile(r"\bpackage\s+(?!body\b)(\w+)\s+is\b"),
    re.compile(r"\bcontext\s+(\w+)\s+is\b"),
    re.compile(r"\bconfiguration\s+(\w+)\s+of\s+\w+\s+is\b"),
]
# Units that must be in the same library as the unit they belong to
SECONDARY = [
    re.compile(r"\bpackage\s+body\s+(\w+)\s+is\b"),
    re.compile(r"\barchitecture\s+\w+\s+of\s+(\w+)\s+is\b"),
    re.compile(r"\bconfiguration\s+\w+\s+of\s+(\w+)\s+is\b"),
]
LIBRARY = re.compile(r"\blibrary\s+(\w+(?:\s*,\s*\w+)*)\s*;")


def warn(message):
    print(f"vhd: warning: {message}", file=sys.stderr)


def parse(path):
    # latin-1 accepts any byte, and VHDL identifiers are case-insensitive
    code = NOISE.sub(" ", path.read_text(encoding="latin-1")).lower()
    return {
        "code": code,
        "primary": {m[1] for p in PRIMARY for m in p.finditer(code)},
        "secondary": {m[1] for p in SECONDARY for m in p.finditer(code)},
        "libs": {n.strip() for m in LIBRARY.finditer(code) for n in m[1].split(",")},
    }


def refs(info, lib):
    """Names used as <lib>.<name> in a file."""
    return set(re.findall(rf"(?<![\w.]){lib}\s*\.\s*(\w+)", info["code"])) - {"all"}


def assign_libraries(files):
    """Map each file to a library, based on how the files refer to each other."""
    declared_in = {}
    for path, info in files.items():
        for unit in info["primary"]:
            declared_in.setdefault(unit, []).append(path)

    assigned = {}
    pending = []

    def assign(path, lib):
        if path not in assigned:
            assigned[path] = lib
            pending.append(path)
        elif assigned[path] != lib:
            warn(f"{path} is needed in both '{assigned[path]}' and '{lib}'; "
                 f"keeping '{assigned[path]}'")

    def propagate():
        while pending:
            path = pending.pop()
            lib, info = assigned[path], files[path]
            # work.x means "x in my own library"
            for unit in refs(info, "work"):
                for other in declared_in.get(unit, []):
                    assign(other, lib)
            # keep entities/packages with their architectures/bodies
            for other, other_info in files.items():
                if (info["primary"] & other_info["secondary"]
                        or info["secondary"] & other_info["primary"]):
                    assign(other, lib)

    named = set().union(*(i["libs"] for i in files.values())) - BUILTIN_LIBS
    for lib in sorted(named):
        found = False
        for info in list(files.values()):
            for unit in sorted(refs(info, lib)):
                for path in declared_in.get(unit, []):
                    assign(path, lib)
                    found = True
        if not found:
            warn(f"library '{lib}' is used, but none of these files provide it. "
                 "If it is a vendor or external library, add it by hand.")
    propagate()

    for path in files:
        if path not in assigned:
            assigned[path] = DEFAULT_LIB

    seen = {}
    for unit, paths in sorted(declared_in.items()):
        for path in paths:
            first = seen.setdefault((assigned[path], unit), path)
            if first != path:
                warn(f"'{unit}' is declared in both {first} and {path}")

    return assigned


def render(assigned, standard):
    libraries = {}
    for path, lib in assigned.items():
        libraries.setdefault(lib, []).append(path)

    lines = [
        f"{MARKER}. Run `vhd` again after adding or removing files.",
        "# Delete this line to protect manual edits from being overwritten.",
        f'standard = "{standard}"',
        "",
        "[libraries]",
    ]
    for lib in sorted(libraries):
        lines.append(f"{lib}.files = [")
        # vhdl_ls reads these entries as glob patterns, hence the escaping
        lines += [f"  {json.dumps(glob.escape(p), ensure_ascii=False)},"
                  for p in sorted(libraries[lib])]
        lines.append("]")
    return "\n".join(lines) + "\n"


def main():
    parser = argparse.ArgumentParser(prog="vhd", description=__doc__)
    parser.add_argument("-r", "--recursive", action="store_true",
                        help="also include files in subdirectories")
    parser.add_argument("-f", "--force", action="store_true",
                        help=f"overwrite a hand-written {OUTPUT}")
    parser.add_argument("--std", choices=["1993", "2008", "2019"], default="2008",
                        help="VHDL standard (default: %(default)s)")
    args = parser.parse_args()

    root = Path.cwd()
    candidates = root.rglob("*") if args.recursive else root.iterdir()
    paths = sorted(p for p in candidates
                   if p.suffix.lower() in (".vhd", ".vhdl") and p.is_file())
    if not paths:
        sys.exit(f"vhd: no .vhd or .vhdl files in {root}")

    output = root / OUTPUT
    if output.exists() and not args.force:
        if not output.read_text(errors="replace").startswith(MARKER):
            sys.exit(f"vhd: {output} was not generated by vhd; use -f to overwrite")

    files = {p.relative_to(root).as_posix(): parse(p) for p in paths}
    assigned = assign_libraries(files)
    output.write_text(render(assigned, args.std), encoding="utf-8")
    print(f"vhd: wrote {output} ({len(files)} files, "
          f"libraries: {', '.join(sorted(set(assigned.values())))})")


if __name__ == "__main__":
    main()
